package io.fulfillx.payment;
import com.fasterxml.jackson.databind.ObjectMapper;import io.fulfillx.payment.application.PaymentCommandService;import io.fulfillx.payment.messaging.PaymentEnvelope;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.testcontainers.junit.jupiter.Container;import org.testcontainers.junit.jupiter.Testcontainers;import org.testcontainers.postgresql.PostgreSQLContainer;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @Testcontainers @ActiveProfiles("local") class PaymentCommandIntegrationTest{
 @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("payment.messaging.consumer-enabled",()->"false");r.add("payment.outbox.publisher-enabled",()->"false");}
 @Autowired MockMvc mvc;@Autowired PaymentCommandService commands;@Autowired ObjectMapper mapper;@Autowired JdbcTemplate jdbc;
 @BeforeEach void clear(){jdbc.update("DELETE FROM payment_outbox");jdbc.update("DELETE FROM processed_messages");jdbc.update("DELETE FROM payments");}
 @Test void successAuthorizationAndDifferentMessageIdAreBusinessIdempotent(){UUID order=UUID.randomUUID();var c=command("AuthorizePayment",order,mapper.createObjectNode().put("orderId",order.toString()).put("amount",10).put("currency","INR").put("paymentToken","tok_success"));commands.authorize(c);commands.authorize(c);commands.authorize(command("AuthorizePayment",order,mapper.createObjectNode().put("orderId",order.toString()).put("amount",10).put("currency","INR").put("paymentToken","tok_success")));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM payments",Integer.class));assertEquals(1,count("PaymentAuthorized"));assertEquals("AUTHORIZED",jdbc.queryForObject("SELECT status FROM payments WHERE order_id=?",String.class,order));}
 @Test void declineAndUnknownTokenArePermanentBusinessResults(){for(String token:new String[]{"tok_decline","tok_real_card_like"}){UUID order=UUID.randomUUID();commands.authorize(command("AuthorizePayment",order,mapper.createObjectNode().put("orderId",order.toString()).put("amount",0).put("currency","INR").put("paymentToken",token)));}assertEquals(2,count("PaymentDeclined"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM payments WHERE decision_code='INVALID_TOKEN'",Integer.class));}
 @Test void cardFieldsAndNonOpaqueTokensAreRejectedWithoutPersistence(){UUID order=UUID.randomUUID();var payload=mapper.createObjectNode().put("orderId",order.toString()).put("amount",10).put("currency","INR").put("paymentToken","4111111111111111").put("cardNumber","4111111111111111").put("cvv","123");assertThrows(IllegalArgumentException.class,()->commands.authorize(command("AuthorizePayment",order,payload)));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM payments",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM processed_messages",Integer.class));}
 @Test void refundCompensationIsIdempotent(){UUID order=UUID.randomUUID();commands.authorize(command("AuthorizePayment",order,mapper.createObjectNode().put("orderId",order.toString()).put("amount",18.25).put("currency","INR").put("paymentToken","tok_success")));UUID id=jdbc.queryForObject("SELECT payment_id FROM payments WHERE order_id=?",UUID.class,order);var refund=command("RefundPayment",order,mapper.createObjectNode().put("orderId",order.toString()).put("paymentId",id.toString()).put("amount",18.25).put("currency","INR").put("reasonCode","INVENTORY_COMMIT_FAILED"));commands.refund(refund);commands.refund(refund);commands.refund(command("RefundPayment",order,refund.payload()));assertEquals("REFUNDED",jdbc.queryForObject("SELECT status FROM payments WHERE payment_id=?",String.class,id));assertEquals(1,count("PaymentRefunded"));}
 @Test void outboxFailureRollsBackPaymentAndInboxThenRetrySucceeds(){UUID order=UUID.randomUUID();var c=command("AuthorizePayment",order,mapper.createObjectNode().put("orderId",order.toString()).put("amount",5).put("currency","INR").put("paymentToken","tok_success"));jdbc.execute("CREATE FUNCTION fail_payment_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'transient publish staging failure'; END $$");jdbc.execute("CREATE TRIGGER fail_payment_outbox_trigger BEFORE INSERT ON payment_outbox FOR EACH ROW EXECUTE FUNCTION fail_payment_outbox()");try{assertThrows(RuntimeException.class,()->commands.authorize(c));}finally{jdbc.execute("DROP TRIGGER IF EXISTS fail_payment_outbox_trigger ON payment_outbox");jdbc.execute("DROP FUNCTION IF EXISTS fail_payment_outbox()");}assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM payments",Integer.class));commands.authorize(c);assertEquals(1,count("PaymentAuthorized"));}
 @Test void localQueueBootstrapDefinesDlqsAndRedriveLimit(){String init;try{init=java.nio.file.Files.readString(java.nio.file.Path.of("../../infrastructure/local/localstack/init/10-create-messaging.py"));}catch(Exception ex){throw new AssertionError("LocalStack messaging bootstrap must be present",ex);}assertTrue(init.contains("maxReceiveCount\": \"5\""));assertTrue(init.contains("PAYMENT_COMMANDS_DLQ"));assertTrue(init.contains("ORDER_RESULTS_DLQ"));assertTrue(init.contains("NOTIFICATION_EVENTS_DLQ"));assertTrue(init.contains("PaymentAuthorized"));assertTrue(init.contains("PaymentRefunded"));assertTrue(init.contains("OrderConfirmed"));}
 @Test void actuatorRequiresAdminRoleButHealthIsPublic() throws Exception {mvc.perform(get("/actuator/health")).andExpect(status().isOk());mvc.perform(get("/actuator/prometheus")).andExpect(status().isUnauthorized());mvc.perform(get("/actuator/prometheus").with(jwt().authorities(()->"ROLE_OPERATIONS"))).andExpect(status().isForbidden());mvc.perform(get("/actuator/prometheus").with(jwt().authorities(()->"ROLE_ADMIN"))).andExpect(status().isOk());}
 private int count(String type){return jdbc.queryForObject("SELECT COUNT(*) FROM payment_outbox WHERE message_type=?",Integer.class,type);}
 private PaymentEnvelope command(String type,UUID order,com.fasterxml.jackson.databind.JsonNode payload){UUID msg=UUID.randomUUID();return new PaymentEnvelope(msg,type,1,Instant.now(),order,msg,"Order",order,payload);}
}


